export interface SoteriaEvent { seq: number; t: number; type: string; [key: string]: unknown }
export interface SoteriaDecision {
  status: 'decided' | 'blocked';
  code?: string;
  measures: { code: string; label: string }[];
  tier?: 1 | 2 | 3;
  tierLabel?: string;
  keysNeeded?: number;
  grants?: string[];
  reasonLabel?: string;
  coverage?: { answered: number; asked: number };
  receiptHash?: string;
  decidedBy?: 'llm' | 'policy_fallback' | 'policy';
  model?: string;
  rationale?: string;
}
type SoteriaResult = Pick<IncidentAlert, 'recommendation' | 'soteriaTier' | 'marketSensitive'> & {
  caseId: string;
  trainId: string;
  consensus: SoteriaConsensusItem[];
  decision: SoteriaDecision;
  events: SoteriaEvent[];
};
export const SOTERIA_BY_INCIDENT = SOTERIA_EXPORT as unknown as Record<string, SoteriaResult>;

