interface RawWagon {
  wagon_id: string;
  wagon_type: 'standard' | 'refrigerated';
  cargo_class: string;
}

interface RawTrain {
  train_id: string;
  locomotive: { position: string; cab: string };
  wagon_count: number;
  wagons: RawWagon[];
}

interface RawIncident {
  incident_id: string;
  train_id: string;
  timestamp: string;
  location: string;
  reporter_role: string;
  incident_type: string;
  symptom: string;
  obstruction: {
    present: boolean;
    type: string;
    position: string;
    blocking_track: boolean;
  };
  affected_wagons: { wagon_id: string; damage_description: string }[];
  train_operational: 'normal' | 'restricted' | 'immobilized';
  track_blocked: boolean;
  severity: 'low' | 'medium' | 'high';
}

